const id = String($json.params?.id ?? '').trim();
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const valid = uuidPattern.test(id);
return [{ json: { valid, execution_id: valid ? id : null, response: valid ? null : { error: 'bad_request', message: 'Parametro de historico invalido.' } } }];
